/*
This shader is a lazy hack of these fantastic works:
[Buffer A] "STELLAR CLOUDS" by alro at https://www.shadertoy.com/view/DtdSz7
[Buffer B] "starfield + dark dust 3" by FabriceNeyret2 at https://www.shadertoy.com/view/WstBWn
*/

// thanks yasuo https://www.shadertoy.com/view/7sc3Dr
float elasticInOut(float t, float overshoot, float damp) {
  return t < 0.5
    ? 0.5 * sin(+overshoot * HPI * 2.0 * t) * pow(2.0, +damp * (2.0 * t - 1.0))
    : 0.5 * sin(-overshoot * HPI * 2.0 * t) * pow(2.0, -damp * (2.0 * t - 1.0)) + 1.0;
}

float gauss(float x) {
    return exp(-0.5*x*x);
}

// fast Airy intensity, thanks FabriceNeyret2
float fA(float x) {
    return (abs(x) < 1.88)? gauss(x / 1.4): (abs(x) > 6.0)? 1.35/abs(x*x*x): (gauss(x/1.4) + 2.7/abs(x*x*x))/2.0;
}

float sdBox(in vec3 p, in mat3 o, in vec3 s) {
    vec3 op = abs(p*o) - s;
    return min(max(op.x, max(op.y, op.z)), 0.0) + length(max(op, 0.0));
}

float sdCyl(in vec3 p, in mat3 o, in float h, in float r) {
    vec3 op = p*o;
    vec2 d = abs(vec2(length(op.xy),op.z)) - vec2(r,h);
    return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}

vec3 tapeLoc = vec3(0.0);
mat3 tapeBasis = mat3(1.0);
vec3 carLoc = vec3(0.0);
mat3 carBasis = mat3(1.0);
vec3 redlight = vec3(0.0);
vec3 bluelight = vec3(0.0);

float sdTape(in vec3 _l) {
    float d = zfar;
    vec3 l = _l + vec3( 0.0, 0.0, 0.2 * fbm(_l.xy * vec2(0.05, 0.5) + iTime * vec2(2.0, 1.0), 0.25, 2));
    d = min(d, sdBox(l - tapeLoc, tapeBasis, vec3(eps, max(eps, iTime*50.0 - 175.0), 0.25)));
    return d;
}

float sdWindows(in vec3 _l) {
    vec3 l = carBasis * (_l - carLoc);

    float d = zfar;
    // blue windows
    d = min(d, sdBox(l - vec3( 0.0,-0.2, 0.0), mat3(1.0), 1.0-vec3( 0.2+l.y*0.333, 0.3,-0.2+l.y*0.333)));
    d = min(d, sdBox(l - vec3( 0.0,-0.2, 0.0), mat3(1.0), 1.0-vec3(-0.2+l.y*0.333, 0.3, 0.2+l.y*0.333)));

    return d;
}

float sdHeadlights(in vec3 _l) {
    vec3 l = carBasis * (_l - carLoc);

    float d = zfar;
    // headlights 
    d = min(d, sdBox(l - vec3(0.0,-1.3, 1.0), mat3(1.0), vec3(5.0, 0.15, 0.3)));
    d = min(d, sdBox(l - vec3(0.0,-1.3,-1.0), mat3(1.0), vec3(5.0, 0.15, 0.3)));

    return d;
}

float sdCar(in vec3 _l) {
    vec3 l = carBasis * (_l - carLoc);

    float d = zfar;
    // main body
    d = min(d, sdBox(l - vec3( 0.0,-0.2, 0.0), mat3(1.0), 1.0-vec3(l.y*0.333, 0.2,-0.15+l.y*0.333)));
    d = min(d, sdBox(l - vec3( 0.0,-1.5, 0.0), mat3(1.0), vec3(2.5, 0.5, 1.5)));
    d = min(d, sdBox(l - vec3( 0.0,-2.0, 0.0), mat3(1.0), vec3(1.9-l.y*0.333, 0.1, 0.9-l.y*0.333)));
    // wheel wells
    d = max(d,-sdCyl(l - vec3( 1.5,-2.0, 0.0), mat3(1.0), 2.0, 0.6));
    d = max(d,-sdCyl(l - vec3(-1.5,-2.0, 0.0), mat3(1.0), 2.0, 0.6));
    // wheels
    d = min(d, sdCyl(l - vec3( 1.5,-2.0,-1.2), mat3(1.0), 0.2, 0.4) - 0.1);
    d = min(d, sdCyl(l - vec3(-1.5,-2.0,-1.2), mat3(1.0), 0.2, 0.4) - 0.1);
    d = min(d, sdCyl(l - vec3( 1.5,-2.0, 1.2), mat3(1.0), 0.2, 0.4) - 0.1);
    d = min(d, sdCyl(l - vec3(-1.5,-2.0, 1.2), mat3(1.0), 0.2, 0.4) - 0.1);
    // bumper
    d = min(d, sdBox(l - vec3( 2.5,-1.7, 0.0), mat3(1.0), 0.5+vec3(0.1+l.y*0.333, 0.2, 1.0)));
    // spoiler
    d = min(d, sdBox(l - vec3(-l.y*0.666-3.0,-0.8, 0.0), mat3(1.0), vec3(-0.2-l.y*0.333, 0.2, 1.5)));

    return d;
}

float sdf(in vec3 l) {
    float d = zfar;
    d = min(d, sdTape(l));
    d = min(d, sdCar(l));
    return d;
}

// Thanks Nimitz https://www.shadertoy.com/view/Xts3WM
vec4 norcurv(in vec3 p, in float sdp, in float ep) {
    vec2 e = vec2(-1.0, 1.0)*ep;
    float t1 = sdf(p + e.yxx), t2 = sdf(p + e.xxy);
    float t3 = sdf(p + e.xyx), t4 = sdf(p + e.yyy);
    return vec4(normalize(e.yxx*t1 + e.xxy*t2 + e.xyx*t3 + e.yyy*t4), (t1+t2+t3+t4 - 4.0*sdp)/(ep*ep));
}

vec3 raymarch(in vec3 rayPos, in vec3 rayDir, const int MAX_STEPS, out float t, out float sd) {
    t = eps;
    float inside = sign(sdf(rayPos));
    float relax = 0.8;
    float lastT = t;
    for (int i = 0; i < MAX_STEPS; i++) {
        sd = sdf(rayPos + rayDir * t) * inside;
        if (sd < eps) {
            if (relax < 0.8)
                break;
            relax = 0.5;
            t = lastT;
        }
        lastT = t;
        t += sd * relax;
        if (t > zfar)
            break;
    }
    return rayPos + rayDir * t;
}

vec4 getSurface(in vec3 rd, in vec3 l, in float sd) {

    if (sd > eps)
        return vec4(0.0);

    vec4 nc = norcurv(l, sd, eps);

    if (sdTape(l) < eps) {
        vec2 tapeTexcoords = fract((l - tapeLoc) * 0.3 * tapeBasis - 0.49).yz;

        // crime scene - do not cross
        float textDist = texture(iChannel2, tapeTexcoords).w;
        float text = smoothstep(0.01, 0.02, textDist);

        vec3 rfl = reflect(rd, nc.xyz);
        float diffuse = max(0.0, dot(nc.xyz, normalize(vec3(0.0, 1.0, -1.0))));
        float specular = 0.99 * smoothstep(-0.2, -0.1, rfl.y - rfl.x * 0.15) -
                         0.99 * smoothstep(-0.1, -0.0, rfl.y - rfl.x * 0.15);

        return vec4(1.2 * diffuse * vec3(0.2,0.4,0.8) * text + specular, step(nc.y, 0.2));
    }

    if (sdCar(l) < eps) {

        vec3 rfl = reflect(rd, nc.xyz);
        vec3 ld = normalize(vec3(-1.0, 0.0, 0.1));
        float diffuse = max(0.0, dot(nc.xyz, ld));
        float specular = pow(max(0.0, dot(rfl, ld)), 128.0);

        return vec4(specular * vec3(0.1,0.1,1.0) + vec3(0.,0.,step(sdWindows(l),eps)) + vec3(step(sdHeadlights(l),eps)), 1.0);
    }

    return vec4(0.0);
}

float doStar(in vec2 uv, in vec2 pt) {
    vec2 d = uv-pt;
    d = rotate2d(d, QTRPI);
    float I = fA(length(d));
    I += 0.1* fA(length(d * vec2(10.0,0.2)));
    I += 0.1* fA(length(d * vec2(0.2,10.0)));
    return I;
}

void doText(inout vec4 fragColor, in vec2 uv) {
    float textDist = texture(iChannel2, uv).w;
    float text = 1.0 - smoothstep(0.01, 0.02, textDist);
    if (uv.y < 0.16) {
        // genuary police!
        fragColor = mix(fragColor, vec4(1.0, 0.2, 0.4, 1.0), max(0.0, 1.0 - textDist * 8.0));
        fragColor = mix(fragColor, vec4(0.4, 0.2, 1.0, 1.0), text);
    } else if (uv.y < 0.32) {
        // busted by the
        fragColor = mix(fragColor, vec4(1.0, 1.0, 1.0, 1.0), 0.2 * max(0.0, 1.0 - textDist * 8.0));
        fragColor = mix(fragColor, vec4(1.0, 1.0, 1.0, 1.0), text);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    ivec2 fc = ivec2(fragCoord);
    vec4 nebula = texelFetch(iChannel0, fc, 0);
    vec4 stars = texelFetch(iChannel1, fc, 0);
    // depth from stellar clouds
    float nebulaDepth = nebula.w * 0.1;
    // depth from redshift
    float starDepth = clamp(stars.g * stars.b / max(0.0001, stars.r), 0.0, 1.0);
    // additive blend
    fragColor = vec4(nebula.rgb + stars.rgb * nebulaDepth * starDepth, 1.0);

    // animate sdf scene
    tapeLoc = vec3(-4.1, -1.6, 5.0); 
    tapeBasis = (basis(vec3(rotate2d(vec2(0.0, 1.0), 0.1), 0.0)));

    carLoc = mix(
        vec3(-28.0, 0.9, 25.0), vec3(0.0, 0.9, 10.0),
        elasticInOut(iTime*0.333, 1.2, 6.0)
    );
    vec3 carFwd = normalize(vec3(-0.666, 0.0, 1.0));
    carBasis = basisUp(carFwd);

    // render
    vec2 uv = fragCoord / iResolution.xy;
    float asp = iResolution.x / iResolution.y;
    vec2 ndc = uv * 2.0 - 1.0;
    vec2 ndca = ndc * vec2(asp, 1.0);

    // current camera view proj matrices
    mat4 view = viewMat(vec3(0.0), vec3(0.0, 0.0, 1.0));
    mat4 proj = projectionMat(vec2(0.0), asp, 53.0);
    vec3 ro, rd;
    getCameraRay(view, proj, ndc, ro, rd);

    float t, sd;
    vec4 scene = getSurface(rd, raymarch(vec3(0.0), rd, 192, t, sd), sd);
    fragColor = mix(fragColor, scene, scene.w);

    // siren lights fx
    redlight = vec3(0.5, 0.8, 1.0) * carBasis + carLoc;
    bluelight = vec3(0.5, 0.8, -1.0) * carBasis + carLoc;
    fragColor.rgb += vec3(1.0,0.1,0.1)*(5.0+4.0*sin(iTime*PI*TWOPI))*doStar(ndca*20.0, vec2(asp, 1.0)*reprojCoordsNDC(view, proj, redlight).xy*20.0);
    fragColor.rgb += vec3(0.1,0.1,1.0)*(5.0-4.0*sin(iTime*PI*TWOPI))*doStar(ndca*20.0, vec2(asp, 1.0)*reprojCoordsNDC(view, proj, bluelight).xy*20.0);

    // busted by the genuary police
    if (iTime > 2.5) {
        float rtime = elasticInOut((iTime - 1.5)*0.5, 5.0, 8.0);
        float scl = clamp(1.0 / rtime, 0.5, 100.0);
        doText(fragColor, ((uv * 2.0 - vec2(1.0, 0.5)) * scl) * 0.5 + vec2(0.5, 0.25) );
    }
}

