// \0/ Shader of the Week!

#define PI 3.14159
#define TWO_PI (2.0 * PI)

// Variable iterator initializer to stop loop unrolling
#define ZERO (min(iFrame,0))

float saturate(float x){
	return clamp(x, 0.0, 1.0);
}

/*
    Volumetric clouds with gyroid noise
    See https://www.shadertoy.com/view/3sffzj for more detailed comments on clouds.
*/

// Different step counts for full and interactive states
#define STEPS_PRIMARY 32
#define STEPS_LIGHT 16

// Offset the sample point by blue noise to get rid of banding
#define DITHERING
const float goldenRatio = 1.61803398875;

// Scattering coefficient based on Earth's atmosphere but tweaked for this look
const vec3 BETA_RAYLEIGH = 100.0*vec3(0.05802, 0.14558, 0.331);
const vec3 BETA_OZONE = vec3(0.650, 1.881, 0.085);

// Scattering
const vec3 sigmaS = 2.0*(BETA_RAYLEIGH);
// Absorption
const vec3 sigmaA = 4.0*(BETA_RAYLEIGH + 3.0*BETA_OZONE);
// Extinction
const vec3 sigmaE = sigmaA; // + sigmaS

const float sunLocation = -1.0;
const float sunHeight = 0.5;

// Main light power
const float power = 200.0;

// For size of AABB
#define CLOUD_EXTENT 10.0
const vec3 minCorner = vec3(-CLOUD_EXTENT, -CLOUD_EXTENT, -CLOUD_EXTENT);
const vec3 maxCorner = vec3(CLOUD_EXTENT, CLOUD_EXTENT, CLOUD_EXTENT);

//-------------------------------- Camera --------------------------------

vec3 rayDirection(float fieldOfView, vec2 fragCoord) {
    vec2 xy = fragCoord - iResolution.xy / 2.0;
    float z = (0.5 * iResolution.y) / tan(radians(fieldOfView) / 2.0);
    return normalize(vec3(xy, -z));
}

// https://www.geertarien.com/blog/2017/07/30/breakdown-of-the-lookAt-function-in-OpenGL/
mat3 lookAt(vec3 targetDir, vec3 up){
  vec3 zaxis = normalize(targetDir);    
  vec3 xaxis = normalize(cross(zaxis, up));
  vec3 yaxis = cross(xaxis, zaxis);

  return mat3(xaxis, yaxis, -zaxis);
}

//-------------------------------- Intersection --------------------------------

// https://gist.github.com/DomNomNom/46bb1ce47f68d255fd5d
// Compute the near and far intersections using the slab method.
// No intersection if tNear > tFar.
vec2 intersectAABB(vec3 rayOrigin, vec3 rayDir, vec3 boxMin, vec3 boxMax) {
    vec3 tMin = (boxMin - rayOrigin) / rayDir;
    vec3 tMax = (boxMax - rayOrigin) / rayDir;
    vec3 t1 = min(tMin, tMax);
    vec3 t2 = max(tMin, tMax);
    float tNear = max(max(t1.x, t1.y), t1.z);
    float tFar = min(min(t2.x, t2.y), t2.z);
    return vec2(tNear, tFar);
}

bool insideAABB(vec3 p){
    float eps = 1e-4;
	return  (p.x > minCorner.x-eps) && (p.y > minCorner.y-eps) && (p.z > minCorner.z-eps) && 
			(p.x < maxCorner.x+eps) && (p.y < maxCorner.y+eps) && (p.z < maxCorner.z+eps);
}

bool getCloudIntersection(vec3 org, vec3 dir, out float distToStart, out float totalDistance){
	vec2 intersections = intersectAABB(org, dir, minCorner, maxCorner);

    if(insideAABB(org)){
        intersections.x = 1e-4;
    }

    distToStart = intersections.x;
    totalDistance = intersections.y - intersections.x;
    return intersections.x > 0.0 && (intersections.x < intersections.y);
}

// https://www.shadertoy.com/view/3s3GDn
float getGlow(float dist, float radius, float intensity){
	return max(0.0, pow(radius/max(dist, 1e-5), intensity));	
}

//-------------------------------- Random --------------------------------

// https://www.shadertoy.com/view/4djSRW
vec3 hash(vec3 p3){
    p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 33.33);
    return 2.0 * fract((p3.xxy + p3.yxx) * p3.zyx) - 1.0;
}

//-------------------------------- Shape --------------------------------

// https://en.wikipedia.org/wiki/Gyroid
// https://www.shadertoy.com/view/wddfDM
float gyroid(vec3 p, float thickness, float bias, float frequency){
    return clamp(abs(dot(sin(p*0.5), cos(p.zxy*1.23) * frequency) - bias) - thickness, 0.0, 3.0)/3.0;
}

// Gyroid noise based on https://www.shadertoy.com/view/3l23Rh
float fbm(vec3 p){

    const int octaves = 12;
    const float fbmScale = 1.95;

    // Rotation of the gyroid every iteration to produce a noise look
    const float a = PI / float(octaves);
    const mat3 m3 = fbmScale * mat3(cos(a), sin(a), 0, -sin(a), cos(a), 0, 0, 0, 1);


    float weight = 0.0;
    float amplitude = 1.0;
    float frequency = 1.0;
    float res = 0.0;


    for(int i = min(0, iFrame); i < octaves; i++){
        res += amplitude * gyroid(p, 0.1, 0.0, frequency);
        p *= m3;
        weight += amplitude;
        amplitude *= (i < 4 ? 0.9 : 0.7);
        frequency *= (i < 3 ? 0.65 : 0.78);
    }

    return saturate(res / weight);
}

float clouds(vec3 p){
    if(!insideAABB(p)){
        return 0.0;
    }
    float noise = fbm(0.25*p);
    float structure = smoothstep(3.0, 5.0, length(p)) * smoothstep(0.05, 0.1, noise);
    float haze = smoothstep(2.0, 10.0, length(p)) * smoothstep(0.02, 0.5, noise);
    return 3e-4+(0.5*haze + 0.75 * structure);

}


//-------------------------------- Stars --------------------------------

// https://iquilezles.org/articles/palettes/
vec3 getColour(float t){
    vec3 a = vec3(0.65);
    vec3 b = 1.0 - a;
    vec3 c = vec3(1.0,1.0,1.0);
    vec3 d = vec3(0.15,0.5,0.75);

    return pow(a + b * cos(TWO_PI * (c * t + d)), vec3(2.2));
}


// Stars with random placement and strength
vec3 getStars(vec3 p){
    p *= 0.2;
    vec3 rand;
    float d = 1e10;
    vec3 cell;

    for(int x = -1; x <= 1; x++){
        for(int y = -1; y <= 1; y++){
            for(int z = -1; z <= 1; z++){
                vec3 c = floor(p) + vec3(x, y, z);
                vec3 h = hash(c);
                vec3 f = c + 0.5 + 0.5 * h;
                float dd = length(p - f);
                if(dd < d){
                    d = dd;
                    rand = h;
                    cell = c;
                }
            }
        }
    }
    rand = clamp(0.5 + 0.5 * rand, 0.0, 1.0);
    vec3 rand2 = clamp(0.5 + 0.5 * hash(cell+vec3(3.12, 104.9, -9.5)), 0.0, 1.0);
    return vec3(0.05) * rand.z * step(0.45, rand2.z) * mix(vec3(1), getColour(rand.y), 0.3) * smoothstep(0.5, 0.0, d) * getGlow(d, 0.25, 2.0);
}

//-------------------------------- Lighting --------------------------------

float HenyeyGreenstein(float g, float costh){
	return (1.0 / (4.0 * 3.1415))  * ((1.0 - g * g) / pow(1.0 + g*g - 2.0*g*costh, 1.5));
}

// https://twitter.com/FewesW/status/1364629939568451587/photo/1
vec3 multipleOctaves(float extinction, float mu, float stepL){

    vec3 luminance = vec3(0);
    const float octaves = 6.0;

    // Attenuation
    float a = 1.0;
    // Contribution
    float b = 1.0;
    // Phase attenuation
    float c = 1.0;

    float phase;

    for(float i = 0.0; i < octaves; i++){
        // Two-lobed HG
        phase = mix(HenyeyGreenstein(-0.1 * c, mu), HenyeyGreenstein(0.3 * c, mu), 0.7);
        luminance += b * phase * exp(-stepL * extinction * sigmaE * a);
        // Lower is brighter
        a *= 0.3;
        // Higher is brighter
        b *= 0.5;
        c *= 0.5;
    }
    return luminance;
}

// Get the amount of light that reaches a sample point.
vec3 lightRay(vec3 org, vec3 p, float phaseFunction, float mu, vec3 sunDirection){

	float lightRayDistance = CLOUD_EXTENT*0.25;
    float distToStart = 0.0;

    getCloudIntersection(p, sunDirection, distToStart, lightRayDistance);

    float stepL = lightRayDistance/float(STEPS_LIGHT);

	float lightRayDensity = 0.0;

	// Collect total density along light ray.
	for(int j = 0; j < STEPS_LIGHT; j++){
		lightRayDensity += clouds(p + sunDirection * float(j) * stepL);
	}

	vec3 beersLaw = multipleOctaves(lightRayDensity, mu, stepL);

    // Return product of Beer's law and powder effect depending on the 
    // view direction angle with the light direction.
	return mix(beersLaw * 2.0 * (1.0 - (exp( -stepL * lightRayDensity * 2.0 * sigmaE))), 
               beersLaw, 
               0.5 + 0.5 * mu);
}

//-------------------------------- Raymarching --------------------------------

// Get the colour along the main view ray.
vec4 mainRay(vec3 org, vec3 dir, vec3 sunDirection, out vec3 totalTransmittance, float offset){

	// Variable to track transmittance along view ray. 
    // Assume clear sky and attenuate light when encountering clouds.
	totalTransmittance = vec3(1.0);

	// Default to black.
	vec3 colour = vec3(0.0);

    // The distance at which to start ray marching.
    float distToStart = 0.0;

    // The length of the intersection.
    float totalDistance = 0.0;

    // Determine if ray intersects bounding volume.
	// Set ray parameters in the cloud layer.
	bool renderClouds = getCloudIntersection(org, dir, distToStart, totalDistance);

	if(!renderClouds){
		return vec4(colour, totalDistance);
    }

	// Sampling step size.
    float stepS = totalDistance / float(STEPS_PRIMARY); 

    // Offset the starting point by blue noise.
    distToStart += stepS * offset;

    // Track distance to sample point.
    float dist = distToStart;

    // Initialise sampling point.
    vec3 p = org + dist * dir;

    float mu = dot(dir, sunDirection);
    // Combine backward and forward scattering to have details in all directions.
	float phaseFunction = mix(HenyeyGreenstein(-0.3, mu), HenyeyGreenstein(0.3, mu), 0.7);

    vec3 sunLight = vec3(1) * power;

	for(int i = 0; i < STEPS_PRIMARY; i++){

        float density = clouds(p);

        vec3 sampleSigmaS = sigmaS * density;
        vec3 sampleSigmaE = sigmaE * density;

        // If there is a cloud at the sample point.
        if(density > 0.0 ){

            // Stars in the clouds
            vec3 ambient = 1.0*getStars(p) + 
                           2.0*getStars(1.5*p + 17.51) + 
                           1.0*getStars(2.4*p - 6.2) +
                           getStars(3.7*p + 109.9);

            // Scale starlight by the density at the sample point
            ambient *= smoothstep(1e-3, 2e-3, density);

            // Amount of sunlight that reaches the sample point through the cloud 
            // is the combination of ambient light and attenuated direct light.
            vec3 luminance = ambient + sunLight * phaseFunction * 
                                        lightRay(org, p, phaseFunction, mu, sunDirection);

            // Scale light contribution by density of the cloud.
            luminance *= sampleSigmaS;

            // Beer-Lambert.
            vec3 transmittance = exp(-sampleSigmaE * stepS);

            // Better energy conserving integration
            // "From Physically based sky, atmosphere and cloud rendering in Frostbite" 5.6
            // by Sebastian Hillaire.
            colour += 
                totalTransmittance * (luminance - luminance * transmittance) / sampleSigmaE; 

            // Attenuate the amount of light that reaches the camera.
            totalTransmittance *= transmittance;  

            // If ray combined transmittance is close to 0, nothing beyond this sample 
            // point is visible, so break early.
            if(length(totalTransmittance) <= 0.001){
                totalTransmittance = vec3(0.0);
                return vec4(colour, dist);
            }
        }

        dist += stepS;

		// Step along ray.
		p = org + dir * dist;
	}

	return vec4(colour, dist);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    ivec2 fc = ivec2(fragCoord);

    float framesToDraw = 1.0;
    float framesDrawn = texelFetch(iChannel0, ivec2(0, iResolution.y-1.), 0).x;
    bool renderFull = framesDrawn < framesToDraw;

    if(renderFull){

        //----------------- Define a camera -----------------

        // Get the default direction of the ray (along the negative Z direction)
        vec3 rayDir = rayDirection(55.0, fragCoord);

        float CAMERA_DIST = 0.01;
        vec2 polarAngles = vec2(-2.1, 2.2);
        vec3 cameraPos = CAMERA_DIST * normalize(vec3(-cos(polarAngles.x) * sin(polarAngles.y), 
                                             cos(polarAngles.y), 
                                            -sin(polarAngles.x) * sin(polarAngles.y)));

        vec3 targetDir = -cameraPos;

        vec3 up = vec3(0.0, 1.0, 0.0);

        // Get the view matrix from the camera orientation
        mat3 viewMatrix = lookAt(targetDir, up);

        // Transform the ray to point in the correct direction
        rayDir = normalize(viewMatrix * rayDir);

        //---------------------------------------------------

        vec3 sunDirection = normalize(vec3(cos(sunLocation), sunHeight, sin(sunLocation)));

        vec3 background = 0.05 * vec3(0.09, 0.33, 0.81);

        float mu = 0.5+0.5*dot(rayDir, sunDirection);
        background += getGlow(1.0-mu, 0.00015, 0.9);

        vec3 totalTransmittance = vec3(1.0);

        float offset = 0.0;

        #ifdef DITHERING
        // From https://blog.demofox.org/2020/05/10/ray-marching-fog-with-blue-noise/
        float blueNoise = r21(genSeed(1, -fc) & 0xFFFF);
        offset = fract(blueNoise + float(iFrame%32) * goldenRatio);
        #endif

        vec4 col = mainRay(cameraPos, rayDir, sunDirection, totalTransmittance, offset); 

        col.rgb += background * totalTransmittance;

        // Tonemapping
        col.rgb = ACESFilm(col.rgb);
        // Gamma
        col.rgb = pow(col.rgb, vec3(0.4545));

        fragColor = col;

    }else{
        vec4 oldData = texelFetch(iChannel0, fc, 0);
        fragColor = oldData;
    }

    // Store the number of full resolution frames which have been drawn for the current view
    if(fc == ivec2(0, iResolution.y-1.)){
        fragColor = vec4(framesDrawn + 1.0, 0.0, 0.0, 1.0);
    }
}

// math constants
const highp float
    SQRT2 = 1.4142136, SC45 = 0.7071068, D2R = 0.0174533,
    eps = 0.001, ieps = 0.999, epsCol = 0.0039062,
    QTRPI = 0.7853981, HPI = 1.5707963, PI = 3.1415926, TWOPI = 6.2831853,
    iQTRPI = 1.2732396, iHPI = 0.6366197, iPI = 0.3183098, iTWOPI = 0.1591549;
const highp float PHI1 = 1.0 - 1.0 / float(1.61803398);
const highp vec2  PHI2 = 1.0 - 1.0 / pow(vec2(1.32471795), vec2(1.0, 2.0));
const highp vec3  PHI3 = 1.0 - 1.0 / pow(vec3(1.22074408), vec3(1.0, 2.0, 3.0));

// camera properties
const float	znear = 0.03125, zfar = 128.0;
const int MAX_RAY_STEPS = 128;

// generate a z order curve for each pixel/frame
int genSeed(in int f, in ivec2 c) {
    return (c.x + c.y*2 + f) + (c.x*1155 ^ c.y*2244) & 0xFFFF;
}

// r2 low discrepancy sequence
float r21(in int v) {
    return fract(PHI1 * float(v));
}

vec2 r22(in int v) {
    return fract(PHI2 * float(v));
}

vec3 r23(in int v) {
    return fract(PHI3 * float(v));
}

float noise(in vec2 l) {
    vec2 i = floor(l);
    vec2 f = fract(l);
    vec2 m = f * f * (3.0 - 2.0 * f);

    int seed = 1;
    float r00 = r21(genSeed(seed, ivec2(i)               ));
    float r01 = r21(genSeed(seed, ivec2(i) + ivec2(0, 1) ));
    float r10 = r21(genSeed(seed, ivec2(i) + ivec2(1, 0) ));
    float r11 = r21(genSeed(seed, ivec2(i) + ivec2(1, 1) ));

    return mix(mix(r00, r10, m.x), mix(r01, r11, m.x), m.y) - 0.5;
}

float fbm(in vec2 l, in float H, const int oct) {
    float value = 0.0;
    float amplitude = 1.0;
    vec2 shift = vec2(0.0);
    mat2 rot = mat2(cos(0.45), sin(0.45), -sin(0.45), cos(0.45));

    for (int i = 0; i < oct; ++i) {
        value += amplitude * noise(l);
        l = rot * l * 2.0 + shift;
        amplitude *= H;
    }

    return value;
}

vec2 rotate2d(in vec2 v, in float a) {
    float sinA = sin(a);
    float cosA = cos(a);
    return vec2(v.x * cosA - v.y * sinA, v.y * cosA + v.x * sinA);	
}

mat3 basis(in vec3 n) {
    float s = (n.z >= 0.0)? 1.0: -1.0;
    float a = 1.0 / (s + n.z);
    float b = -n.x*n.y*a;
    return mat3(-vec3(b, s - n.y*n.y*a, -n.y), vec3(1.0 - n.x*n.x*a*s, b*s, -n.x*s), n);
}

// orthonormal basis assuming up is +y
mat3 basisUp(in vec3 forward) {
    vec3 down = vec3(0.0, -1.0, 0.0);
    vec3 right = normalize(cross(forward, down));
    return mat3(right, normalize(cross(forward, right)), forward);
}

// fast orthogonal matrix inverse
mat4 orthoInverse(in mat4 m) {
    mat3 r = transpose(mat3(m));
    return mat4(
        vec4(r[0], 0.0),
        vec4(r[1], 0.0),
        vec4(r[2], 0.0),
        vec4(r * -m[3].xyz, 1.0)
    );
}

// construct 4x4 view mat from camera origin, forward direction
mat4 viewMat(in vec3 origin, in vec3 direction) {
    mat3 bas = basisUp(direction);
    return mat4(
        vec4(bas[0], 0.0),
        vec4(bas[1], 0.0),
        vec4(bas[2], 0.0),
        vec4(origin, 1.0)
    );
}

// construct 4x4 projection mat using offaxis parameters, aspect ratio, FOV
mat4 projectionMat(in vec2 offaxis, in float aspect, in float fov) {
    // proj parameters
    float f = zfar;
    float n = znear;
    float fovrad = fov * D2R;
    float r =  n * aspect * tan(0.5 * (fovrad - offaxis.x));
    float l = -n * aspect * tan(0.5 * (fovrad + offaxis.x));
    float t =  n          * tan(0.5 * (fovrad - offaxis.y));
    float b = -n          * tan(0.5 * (fovrad + offaxis.y));
    // construct proj mat
    return mat4(
        2.0*n/(r-l),         0.0, (r+l)/(r-l),           0.0,
                0.0, 2.0*n/(t-b), (t+b)/(t-b),           0.0,
                0.0,         0.0, (f+n)/(f-n), 2.0*f*n/(f-n),
                0.0,         0.0,         1.0,           0.0
    );
}

// project the pixel at ndc into a worldspace ray
void getCameraRay(in mat4 view, in mat4 proj, in vec2 ndc, out vec3 ro, out vec3 rd) {
    ro = view[3].xyz;
    vec4 ndch = transpose(inverse(proj)) * vec4(ndc, 1.0, 1.0);
    rd = normalize(mat3(view) * vec3(ndch.xy, 1.0));
}

// project a worldspace location hl into camera NDC using its view projection
vec3 reprojCoordsNDC(in mat4 view, in mat4 proj, in vec3 hl) {
    vec4 camspace = orthoInverse(view) * vec4(hl, 1.0);
    vec4 ndch = camspace * proj;
    return vec3(ndch.xy / ndch.w, length(camspace));
}

// Thanks mla - https://www.shadertoy.com/view/4cGGWw
vec4 highpTexelFetch(highp sampler2D chan, ivec2 px, int lod) {
    return texelFetch(chan, px, lod);
}

// https://knarkowicz.wordpress.com/2016/01/06/aces-filmic-tone-mapping-curve/
vec3 ACESFilm(vec3 x){
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

// "starfield + dark dust 3" by FabriceNeyret2 at https://www.shadertoy.com/view/WstBWn

// variant of https://shadertoy.com/view/wscfDr
// #if 0/1 line 29 to hide/see stars cross.

#define rot(a)    mat2( cos(a+vec4(0,11,33,0)) )                              // rotation                  

void mainImage(out vec4 O, vec2 U) {    
    float d,l,I,t=3.2;
    vec3  R = iResolution, 
          M = vec3(8,4,0)/1e2*cos(t+vec3(0,11,0)),
          D = normalize(vec3( U+U, -3.5*R.y ) - R ),                          // ray direction
          p = 2./R, L; 
    vec4  r, T = vec4(1), 
          C = exp(-.5*vec4(1,2,4,0)),                                         // dark dust unit transparency
          S = vec4(.2,.3,.9,0);                                               // star color
    O-=O;
    p.xy *= rot( .5+6.*M.y), D.xy *= rot( .5+6.*M.y);                         // camera move 
    p.xz *= rot( 2.-6.*M.x), D.xz *= rot( 2.-6.*M.x);
    p.xy += cos( t + vec2(0,11)) - 2.*t;
    p.x -= iTime*0.01;
    p+=D*3.0;                                                                 // skip the closest ones
    for ( float i=1.; i < 48.; i++,  p += D ) {                               // volume ray-casting
        r = texture( iChannel0, (floor(p)+.5)/32. );                          // per voxel 4 random floats
        // NB: we should either visit neighbor cells or avoid cell margins, but cut spheres are rare
        L = fract(p) - r.rgb ;                                                // distance to sphere in voxel
        d = -dot(L,D);            // distance ray-sphere: d/dl ( || P+l.D - C ||² )  = 2l + 2 (CP.D)
        if (// r.a > .9 &&        // less blue-noise more white noise. but strange artifact
            i>0. || d > 0.)                                                   // for not seeing in our back ;-)
#define PSF(L) ( l = i/length(L) ,  min( 1e9, l*l*l ) ) // light on sensor = Istar * 1/d² * 1/pixeldist³ = Istar * d/dist³, cf https://www.shadertoy.com/results?query=star+psf
            I = PSF( L += d*D ),                                              // L= point on the ray that is closest to sphere
#if 1                             // 1 to see star cross
            L.xz *= rot( -(2.-6.*M.x) ), L.xy *= rot( -(.5+6.*M.y) );         // back to screen-space
            I +=  .3* PSF( L.xy * vec2(10,.2) ),
            I +=  .3* PSF( L.xy * vec2(.2,10) ),
#endif
            O += T *   S * I/(i*i);                                           // blend to final color                     

        l = max(0., 3.*texture( iChannel0, p/128. ).a -2.);                   // random density dark dust transparency
        T *= pow(C, vec4(l));                                                 // cumul opacity
    }
    O = pow(  9e-7* O, vec4(1./2.2) );
    //O = 3e-6*O;
}

