    _rto = vec3(1.0 / 16.0);
}
// dont use directly
vec4 pl(vec2 ltr, vec2 uv) {
    _cur.x += _sz.z * 1.1;
    if (any(lessThan(uv, _cur.xy)) || any(greaterThan(uv, _cur.xy+_sz.xy)))
        return vec4(1.0);
    vec2 dlta = uv - _cur.xy,
    smp = (dlta / _sz.xy * 0.9 + ltr) * _rto.xy;
    return texture(iChannel0, smp, 0.0) - 0.5;
}

